from decimal import Decimal, ROUND_HALF_UP


def tax(amount, rate):
    """Tax on an invoice amount, rounded half up to the cent."""
    result = Decimal(str(amount)) * Decimal(str(rate))
    return float(result.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

